insert into public.activities
  (slug, title, short_description, description, min_age, max_age, duration, category, location, materials, material_tags, adult_help, preparation, steps, tip, premium, image_url)
values
  ('pintura-escondida', 'Pintura escondida', 'Dibujos secretos que aparecen con acuarela.', 'Dibujas en secreto con crayón blanco y tu hijo descubre la sorpresa pintando encima.', 3, 5, 15, 'crear', 'casa', array['papel', 'crayón blanco', 'acuarelas', 'pincel']::text[], array['papel', 'colores']::text[], true, '1 minuto.', array['Haz algunos dibujos con crayón blanco.', 'Entrégale acuarela al niño.', 'Pinten encima y descubran juntos los dibujos.']::text[], 'Dibuja cosas que conozca: un sol, su inicial, una casa.', false, null),
  ('busqueda-de-colores', 'Búsqueda de colores', 'Encuentren en casa cosas de un mismo color.', 'Elige un color y salgan a buscar objetos de ese color por toda la casa.', 2, 5, 5, 'moverse', 'casa', array['una canasta o caja']::text[], array['nada']::text[], false, 'Nada.', array['Elige un color en voz alta.', 'Busquen 5 cosas de ese color.', 'Pónganlas juntas y cuéntenlas.']::text[], 'Para los de 2 años, muéstrale un objeto de referencia.', false, null),
  ('camino-de-cojines', 'Camino de cojines', 'Un río imaginario que solo se cruza saltando.', 'Arma un camino con cojines en el piso y crucen el ''río'' sin tocar el suelo.', 2, 5, 15, 'moverse', 'casa', array['cojines', 'almohadas']::text[], array['nada']::text[], true, '2 minutos.', array['Pon los cojines en fila con espacio entre ellos.', 'Cuéntale que el piso es un río.', 'Crucen saltando de cojín en cojín.']::text[], 'Cambia el orden de los cojines cada ronda.', false, null),
  ('caja-misteriosa', 'Caja misteriosa', 'Adivinar objetos solo con las manos.', 'Esconde objetos en una caja y que adivine qué son tocándolos sin mirar.', 3, 5, 15, 'aprender', 'casa', array['caja de cartón', 'objetos de la casa']::text[], array['carton']::text[], true, '3 minutos.', array['Haz un agujero en la caja para que entre una mano.', 'Mete un objeto sin que lo vea.', 'Que lo toque y adivine qué es.']::text[], 'Usa texturas distintas: una cuchara, una media, una esponja.', false, null),
  ('historias-con-dibujos', 'Historias con dibujos', 'Inventen un cuento dibujando por turnos.', 'Uno dibuja, el otro sigue la historia. Al final tienen un cuento entre los dos.', 4, 5, 30, 'juntos', 'casa', array['papel', 'colores']::text[], array['papel', 'colores']::text[], true, 'Nada.', array['Dibuja un personaje.', 'Pídele que dibuje dónde vive.', 'Sigan por turnos y cuenten la historia al final.']::text[], 'Escribe la frase que diga debajo de cada dibujo.', false, null),
  ('clasificacion-de-objetos', 'Clasificación de objetos', 'Ordenar cosas por tamaño, color o forma.', 'Junten objetos pequeños y organícenlos en grupos según lo que elija.', 3, 5, 15, 'aprender', 'casa', array['tapas', 'bloques o juguetes pequeños', 'recipientes']::text[], array['nada']::text[], false, '2 minutos.', array['Pon todos los objetos sobre la mesa.', 'Dale tres recipientes.', 'Que los ordene como quiera y te cuente por qué.']::text[], 'No hay respuesta incorrecta: pregúntale su criterio.', false, null),
  ('serpientes-de-plastilina', 'Serpientes de plastilina', 'Hacer serpientes largas, cortas y enrolladas.', 'Amasar y estirar plastilina para crear una familia de serpientes.', 2, 4, 15, 'crear', 'casa', array['plastilina']::text[], array['plastilina']::text[], false, 'Nada.', array['Muéstrale cómo rodar la plastilina.', 'Hagan una serpiente larga y una corta.', 'Enrollen una como caracol.']::text[], 'Comparen tamaños: ¿cuál es la más larga?', false, null),
  ('respirar-como-globo', 'Respirar como globo', 'Inflarse y desinflarse despacito.', 'Un momento de calma imaginando que son globos que se inflan y se desinflan.', 2, 5, 5, 'tranquilo', 'cualquier', array[]::text[], array['nada']::text[], true, 'Nada.', array['Siéntense frente a frente.', 'Inhalen abriendo los brazos como un globo.', 'Exhalen despacio bajando los brazos.']::text[], 'Hazlo antes de dormir o después de mucho correr.', false, null),
  ('carretera-de-cinta', 'Carretera de cinta', 'Una pista en el piso para sus carritos.', 'Con cinta de enmascarar construyan calles, curvas y estacionamientos.', 2, 5, 30, 'solo', 'casa', array['cinta de enmascarar', 'carritos']::text[], array['cinta']::text[], true, '5 minutos.', array['Pega una línea larga en el piso.', 'Agrega curvas y un cruce.', 'Déjalo manejar sus carritos por la ciudad.']::text[], 'Dibujen un estacionamiento en un cartón.', false, null),
  ('estatuas-musicales', 'Estatuas musicales', 'Bailar y congelarse cuando para la música.', 'El clásico juego de bailar y quedarse quieto como estatua.', 2, 5, 15, 'moverse', 'casa', array['música']::text[], array['nada']::text[], true, 'Nada.', array['Pon una canción que le guste.', 'Bailen libremente.', 'Pausa la música: ¡todos estatuas!']::text[], 'Propón estatuas de animales.', true, null),
  ('telescopio-de-carton', 'Telescopio de cartón', 'Explorar la casa con un tubo de cartón.', 'Decoren un tubo de papel higiénico y úsenlo para ''espiar'' cosas.', 3, 5, 15, 'crear', 'casa', array['tubo de cartón', 'colores', 'cinta']::text[], array['carton', 'colores', 'cinta']::text[], false, 'Nada.', array['Decoren el tubo con colores.', 'Pongan cinta en los bordes.', 'Salgan a buscar cosas redondas, rojas o pequeñas.']::text[], 'Pídele que te cuente lo que ve como explorador.', true, null),
  ('contar-escalones', 'Contar escalones', 'Contar en voz alta mientras caminan.', 'Una caminata contando pasos, escalones o árboles.', 3, 5, 5, 'aprender', 'afuera', array[]::text[], array['nada']::text[], true, 'Nada.', array['Elijan qué van a contar.', 'Cuenten en voz alta juntos.', 'Al final, ¿cuántos fueron?']::text[], 'Para los de 3 años, lleguen hasta 10.', false, null),
  ('sellos-de-papel', 'Sellos de papel arrugado', 'Pintar con bolitas de papel.', 'Arruguen papel, mójenlo en pintura y hagan sellos con texturas.', 2, 4, 15, 'crear', 'casa', array['papel', 'pintura', 'plato']::text[], array['papel', 'colores']::text[], true, '2 minutos.', array['Pon un poco de pintura en un plato.', 'Arruga una hoja en bolita.', 'Sellen sobre otra hoja.']::text[], 'Pon un periódico debajo y listo.', true, null),
  ('el-cuento-en-la-sabana', 'Cuento bajo la sábana', 'Una carpa rápida y un cuento con linterna.', 'Una sábana sobre dos sillas es suficiente para un rincón mágico.', 2, 5, 15, 'tranquilo', 'casa', array['sábana', 'sillas', 'linterna']::text[], array['nada']::text[], true, '3 minutos.', array['Arma la carpa con la sábana.', 'Entren con un libro y una linterna.', 'Lean bajito, como un secreto.']::text[], 'Deja que él sostenga la linterna.', false, null),
  ('rompecabezas-de-carton', 'Rompecabezas de cartón', 'Cortar un dibujo y armarlo de nuevo.', 'Pega un dibujo sobre cartón, córtalo en piezas y armen juntos.', 3, 5, 30, 'aprender', 'casa', array['cartón', 'dibujo o revista', 'tijeras']::text[], array['carton', 'papel']::text[], true, '5 minutos.', array['Pega el dibujo sobre el cartón.', 'Corta en 4 a 6 piezas.', 'Mézclalas y armen el rompecabezas.']::text[], 'Más piezas para los de 5 años.', true, null),
  ('imitar-animales', 'Imitar animales', 'Moverse como un animal y adivinar cuál es.', 'Por turnos imitan animales y el otro adivina.', 2, 5, 5, 'moverse', 'cualquier', array[]::text[], array['nada']::text[], false, 'Nada.', array['Elige un animal en secreto.', 'Imítalo sin hablar.', 'Que adivine y luego le toca a él.']::text[], 'Usa sonidos si es muy pequeño.', false, null),
  ('cocina-de-plastilina', 'Cocinita de plastilina', 'Preparar comida imaginaria con plastilina.', 'Arepas, galletas y frutas de plastilina para un restaurante imaginario.', 3, 5, 30, 'solo', 'casa', array['plastilina', 'platos de juguete']::text[], array['plastilina']::text[], false, 'Nada.', array['Saca la plastilina y algunos platos.', 'Pídele que cocine algo para ti.', 'Pide un plato del ''menú''.']::text[], 'Pregúntale el precio de cada plato.', true, null),
  ('salto-de-lineas', 'Salto de líneas', 'Saltar sobre líneas de cinta en el piso.', 'Pega líneas de cinta a distintas distancias y salten de una a otra.', 2, 5, 15, 'moverse', 'casa', array['cinta de enmascarar']::text[], array['cinta']::text[], true, '2 minutos.', array['Pega 4 líneas en el piso.', 'Salten con los dos pies.', 'Prueben en un pie o hacia atrás.']::text[], 'Pon números en cada línea para contar.', false, null),
  ('collage-de-revistas', 'Collage de revistas', 'Recortar y pegar cosas que le gustan.', 'Hojeen revistas viejas y armen un collage de cosas favoritas.', 4, 5, 30, 'juntos', 'casa', array['revistas', 'papel', 'pegante', 'tijeras de punta roma']::text[], array['papel']::text[], true, '2 minutos.', array['Busquen imágenes que le gusten.', 'Recórtenlas juntos.', 'Péguenlas en una hoja y pónganle título.']::text[], 'Cuélguenlo en la nevera.', true, null),
  ('escuchar-sonidos', '¿Qué suena?', 'Cerrar los ojos y adivinar sonidos.', 'Un momento tranquilo para escuchar sonidos de la casa.', 2, 5, 5, 'tranquilo', 'cualquier', array[]::text[], array['nada']::text[], true, 'Nada.', array['Pídele que cierre los ojos.', 'Haz un sonido: una puerta, agua, una cuchara.', 'Que adivine qué fue.']::text[], 'Luego cambien: que él haga el sonido.', false, null)
